import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as r,o,af as a}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"Google AI 订阅与额度","description":"","frontmatter":{},"headers":[],"relativePath":"zh/products/ai-coding/gemini/google-pro.md","filePath":"zh/products/ai-coding/gemini/google-pro.md","lastUpdated":1787042982000}'),l={name:"zh/products/ai-coding/gemini/google-pro.md"};function i(d,t,s,n,h,g){return o(),r("div",null,[...t[0]||(t[0]=[a(`<h1 id="google-ai-订阅与额度" tabindex="-1">Google AI 订阅与额度 <a class="header-anchor" href="#google-ai-订阅与额度" aria-label="Permalink to &quot;Google AI 订阅与额度&quot;">​</a></h1><blockquote><p>订阅档位决定你能用哪些模型、用多少、以及有没有 Google Cloud 额度。这一页只讲<strong>付费、额度，以及 Pro 权益怎么画进家族图</strong>。各产品怎么用请看对应产品页。整张四档对照表只在<a href="./gemini-cheatsheet.html#订阅层级">速查表</a>。</p></blockquote><h2 id="先搞清一件事" tabindex="-1">先搞清一件事 <a class="header-anchor" href="#先搞清一件事" aria-label="Permalink to &quot;先搞清一件事&quot;">​</a></h2><p>家族里的产品<strong>不是一份订阅全解锁</strong>，付费入口有两条：</p><table tabindex="0"><thead><tr><th>入口</th><th>覆盖</th><th>面向</th></tr></thead><tbody><tr><td>Google AI 订阅（Plus / Pro / Ultra）</td><td>Gemini 应用、Jules、Antigravity、Flow 等的使用量</td><td>个人开发者</td></tr><tr><td><a href="./code-assist.html">Gemini Code Assist</a> 的 Standard / Enterprise</td><td>IDE 扩展的能力与合规特性</td><td>团队与组织</td></tr></tbody></table><p><strong>买了个人 AI Pro 不会让 Code Assist 变成企业版</strong>，两者是分开的。团队合规需求走的是 Code Assist 的版本，不是个人订阅。</p><p><strong>2026-06-18 起</strong>，个人 / Pro / Ultra 通过「Login with Google」访问 Gemini CLI 与 Code Assist IDE 扩展已停服；个人开发者的终端与 IDE 入口是 <a href="./antigravity.html">Antigravity</a>。Standard / Enterprise 与付费 API key 不受影响。<a href="https://developers.google.com/gemini-code-assist/docs/deprecations/code-assist-individuals" target="_blank" rel="noreferrer">官方弃用说明</a>。</p><h2 id="四个档位" tabindex="-1">四个档位 <a class="header-anchor" href="#四个档位" aria-label="Permalink to &quot;四个档位&quot;">​</a></h2><p>订阅分 <strong>AI Plus / AI Pro / AI Ultra 5x / AI Ultra 20x</strong> 四档。存储、模型倍率、Cloud 额度、Flow 月积分等完整对照见<a href="./gemini-cheatsheet.html#订阅层级">速查表</a>，本页不重复维护。</p><p>几条选档时真正影响判断的事实：</p><p><strong>1. 扩展上下文从 Pro 档起。</strong> 官方对比表标注 Pro 及以上为 100 万令牌。这是家族里唯一可引用的上下文数字。</p><p><strong>2. Google Cloud 额度只有 Pro 及以上有。</strong> 通过 Google Developer Program 提供：Pro US$10/月，Ultra 5x US$40/月，Ultra 20x US$100/月。要走 Gemini API 或 Vertex AI 的话，这是选 Pro 而不是 Plus 的主要理由。</p><p><strong>3. 智能体类产品的额度只有定性描述。</strong> Jules 与 Antigravity 的官方对比表只写「任务数与并发任务数随档位提高」，<strong>没有给具体数字</strong>。</p><p><strong>4. Flow 积分有数字。</strong> 免费每天 50、Plus 200/月、Pro 1,000/月、Ultra 10,000 或 25,000/月。细节只在 <a href="./flow.html#额度">Flow</a>。</p><h2 id="pro-里和编码相关的权益" tabindex="-1">Pro 里和编码相关的权益 <a class="header-anchor" href="#pro-里和编码相关的权益" aria-label="Permalink to &quot;Pro 里和编码相关的权益&quot;">​</a></h2><p>来源：<a href="https://support.google.com/googleone/answer/14534406" target="_blank" rel="noreferrer">Use Google AI Pro benefits</a>。这里只列前端工程师会碰到的项，不把整份订阅清单抄过来。</p><table tabindex="0"><thead><tr><th>权益</th><th>对前端工程师</th><th>去哪看</th></tr></thead><tbody><tr><td><strong>Google Flow</strong></td><td>落地页 / 宣传片 / 产品演示视频</td><td><a href="./flow.html">Flow</a>（额度链到那一页）</td></tr><tr><td><strong>Google Antigravity</strong> 更高额度 + 优先流量</td><td>2026-06-18 后的个人日常入口</td><td><a href="./antigravity.html">Antigravity</a></td></tr><tr><td><strong>Jules</strong> 更高任务数 / 并发 / 新模型</td><td>云端异步 PR</td><td><a href="./jules.html">Jules</a></td></tr><tr><td><strong>Google AI Studio</strong></td><td>调模型、走 API；Pro 对 Gemini 3.1 Pro 与 Nano Banana Pro 有更高上限</td><td><a href="./ai-studio.html">AI Studio</a></td></tr><tr><td><strong>Gemini in Android Studio</strong></td><td>Android 项目里更高的补全与推理额度；代码不用于训练</td><td>不必独立成页；IDE 入口见 <a href="./code-assist.html">Code Assist</a></td></tr><tr><td><strong>Google Developer Program premium</strong></td><td>US$10 Cloud 额度、Code Assist 更高配额、30 个 Firebase Studio 工作区。<strong>不能</strong>和家庭组成员共享</td><td><a href="https://developers.google.com/profile/help/benefits#premium-benefits" target="_blank" rel="noreferrer">Developer Program</a></td></tr><tr><td><strong>Gemini app + Deep Research</strong></td><td>编码之外的深度调研</td><td><a href="https://gemini.google/overview/deep-research/" target="_blank" rel="noreferrer">Deep Research</a></td></tr><tr><td><strong>Gemini Spark</strong>（仅美国）</td><td>Gemini 应用里的个人 agent，按目标自动跑工作流</td><td>不必独立成页；<a href="https://support.google.com/gemini/answer/17094507" target="_blank" rel="noreferrer">官方说明</a></td></tr><tr><td><strong>Gemini Notebook</strong></td><td>研究 / 写作助手；Pro 提高 Audio Overviews 等上限，每本最多 <strong>300</strong> 个 source</td><td>不必独立成页；<a href="https://support.google.com/gemininotebook/answer/16213268" target="_blank" rel="noreferrer">官方说明</a></td></tr><tr><td><strong>Gemini in Chrome auto browse</strong>（仅美国）</td><td>让 Gemini 在 Chrome 里替你跑多步网页任务（比价、订酒店）。需 Chrome 144+</td><td>不必独立成页；<a href="https://support.google.com/gemini/answer/16821166" target="_blank" rel="noreferrer">官方说明</a></td></tr><tr><td><strong>Google Flow Music</strong></td><td>歌曲 / MV；Pro 对应 Flow Music 的 Plus 档：<strong>每月 10,000 音乐积分</strong>（约 2,000 首歌）、12 路并发。<strong>与 Flow 视频积分分开</strong></td><td><a href="https://www.flowmusic.app/" target="_blank" rel="noreferrer">flowmusic.app</a></td></tr></tbody></table><p>额度用尽后，Pro / Ultra 可另购 AI credits，用于 Gemini、<a href="./flow.html">Flow</a>、<a href="./antigravity.html">Antigravity</a>。管理方式见 <a href="https://support.google.com/googleone/answer/16287445" target="_blank" rel="noreferrer">Manage AI credits</a>。</p><h2 id="订阅还带什么" tabindex="-1">订阅还带什么 <a class="header-anchor" href="#订阅还带什么" aria-label="Permalink to &quot;订阅还带什么&quot;">​</a></h2><p>同一份 Pro 还带 Dreambeans（仅美国）、Health Premium、Home Premium、TV Create Hub（仅美国）、Earth 的 Gemini 能力、Photos Remix / Photo to video。<strong>与编码无关</strong>，本站不写。</p><h2 id="该为哪一档付钱" tabindex="-1">该为哪一档付钱 <a class="header-anchor" href="#该为哪一档付钱" aria-label="Permalink to &quot;该为哪一档付钱&quot;">​</a></h2><p>按你<strong>主要用哪个工具</strong>决定，而不是按「哪档功能多」：</p><table tabindex="0"><thead><tr><th>你的主要用法</th><th>建议</th><th>理由</th></tr></thead><tbody><tr><td>只在终端里偶尔问问题</td><td>先用免费额度</td><td>用满了再升，不用提前买</td></tr><tr><td>每天在终端干活（个人账号）</td><td>Pro + <a href="./antigravity.html">Antigravity</a></td><td>2026-06-18 后个人 / Pro / Ultra 不再走 Gemini CLI 的 Login with Google</td></tr><tr><td>每天用 Gemini CLI（Standard / Enterprise 或 API key）</td><td>Pro</td><td>扩展上下文 + Cloud 额度都从这档起</td></tr><tr><td>要走 Gemini API 做集成</td><td>Pro 起</td><td>主要为了 US$10 Cloud 额度</td></tr><tr><td>大量跑 Jules / Antigravity 任务</td><td>Ultra</td><td>并发与任务数随档位提高</td></tr><tr><td>经常出落地页 / 产品演示视频</td><td>Pro 起 + <a href="./flow.html">Flow</a></td><td>月积分从 200 跳到 1,000；免费每天 50 只够试用</td></tr><tr><td>团队有合规硬要求</td><td>走 <a href="./code-assist.html">Code Assist</a> 版本</td><td>个人订阅不提供 VPC-SC / IP 赔偿</td></tr></tbody></table><p><strong>顺序很重要：先把免费额度用到不够用，再升档。</strong> 反过来做你会为没用上的容量付钱，而且不知道自己真实的消耗量级。</p><h2 id="额度不是硬性上限" tabindex="-1">额度不是硬性上限 <a class="header-anchor" href="#额度不是硬性上限" aria-label="Permalink to &quot;额度不是硬性上限&quot;">​</a></h2><p>这是最容易踩的坑：<strong>Google Cloud 额度是「送你的钱」，用完不会自动停，超出部分正常计费。</strong></p><p>必须先设预算再开始跑批量脚本：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GCP 控制台 → 计费 → 预算和警报 → 创建预算</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>金额设成你的额度金额（Pro 档即 US$10）</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>告警阈值：50% / 90% / 100%</span></span></code></pre></div><p><strong>但要注意预算本身只发通知，不会停用服务。</strong> 想要真正的硬停止，官方文档给的方案是把预算通知发到 Pub/Sub，再用一个函数去关掉计费账号的绑定——这需要你自己搭：</p><ul><li><a href="https://cloud.google.com/billing/docs/how-to/notify" target="_blank" rel="noreferrer">设置预算通知</a></li><li><a href="https://cloud.google.com/billing/docs/how-to/disable-billing-with-notifications" target="_blank" rel="noreferrer">用通知自动停用计费</a></li></ul><p>最容易超支的两类操作：<strong>长上下文单次调用</strong>（成本远高于交互式对话）和<strong>无人值守的批量脚本</strong>。这两件事之前，预算一定要先配好。</p><h2 id="安全实践" tabindex="-1">安全实践 <a class="header-anchor" href="#安全实践" aria-label="Permalink to &quot;安全实践&quot;">​</a></h2><p>订阅额度之外，值得配的几条：</p><table tabindex="0"><thead><tr><th>实践</th><th>怎么做</th></tr></thead><tbody><tr><td>让智能体只在可信目录里自动执行</td><td>Gemini CLI 的 <code>security.folderTrust.enabled</code>，见<a href="./gemini-cheatsheet.html#配置速查">速查表</a></td></tr><tr><td>智能体改动隔离在独立分支</td><td>开跑前切分支，事后用 diff 审查</td></tr><tr><td>关键改动人工确认</td><td>Jules 的计划批准、Antigravity 的计划构件</td></tr><tr><td>定期读改动而不是只看结论</td><td>智能体的验证记录只是参考，不能替代 review</td></tr></tbody></table><blockquote><p>⚠️ 历史版本文档里出现过 <code>security.allowedCommands</code> / <code>security.deniedCommands</code> / <code>security.sandboxMode</code> 这类配置键，<strong>官方文档里不存在</strong>。真实存在的安全相关配置只有信任文件夹等少数几项，见<a href="./gemini-cheatsheet.html#配置速查">速查表</a>。</p></blockquote><h2 id="各产品在哪" tabindex="-1">各产品在哪 <a class="header-anchor" href="#各产品在哪" aria-label="Permalink to &quot;各产品在哪&quot;">​</a></h2><p>这一页不重复产品介绍，直接去对应页面：</p><ul><li>终端 → <a href="./gemini-cli.html">Gemini CLI</a></li><li>自主开发平台 → <a href="./antigravity.html">Antigravity</a></li><li>云端异步任务 → <a href="./jules.html">Jules</a></li><li>交互原型 → <a href="./canvas.html">Canvas</a></li><li>落地页 / 宣传片 / 产品演示视频 → <a href="./flow.html">Google Flow</a></li><li>IDE 扩展 → <a href="./code-assist.html">Code Assist</a></li><li>模型与 API → <a href="./ai-studio.html">AI Studio</a></li></ul><h2 id="官方资源" tabindex="-1">官方资源 <a class="header-anchor" href="#官方资源" aria-label="Permalink to &quot;官方资源&quot;">​</a></h2><ul><li><a href="https://one.google.com/about/google-ai-plans/" target="_blank" rel="noreferrer">Google AI 订阅对比</a></li><li><a href="https://support.google.com/googleone/answer/14534406" target="_blank" rel="noreferrer">Google AI Pro 权益清单</a></li><li><a href="https://developers.google.com/program" target="_blank" rel="noreferrer">Google Developer Program</a></li><li><a href="https://cloud.google.com/billing/docs/how-to/budgets" target="_blank" rel="noreferrer">GCP 预算与告警</a></li></ul><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./gemini-cheatsheet.html#订阅层级">速查表</a> — 四档完整对照表</li><li><a href="./gemini-cookbook.html#_14-拿到-google-cloud-额度-怕超支">Cookbook</a> — 预算配置配方</li></ul>`,42)])])}const b=e(l,[["render",i]]);export{f as __pageData,b as default};
